pub(in crate::program_module::runtime) fn read_bounded_line(
    reader: &mut impl BufRead,
) -> Result<Option<InputLine>> {
    let mut bytes = Vec::with_capacity(MAX_INPUT_LINE_BYTES + 1);
    let read = (&mut *reader)
        .take((MAX_INPUT_LINE_BYTES + 1) as u64)
        .read_until(b'\n', &mut bytes)
